  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Life and Human Dignity$j$, $j${"readings": [{"title": "Psalm 139 (King James Version)", "url": "/portal/bible/Psalms/139"}], "body": "The Bible teaches that every human being has worth because God made us in His own image. Genesis 1:27 says, So God created man in his own image, in the image of God created he him; male and female created he them. Psalm 139:13 to 16 describes God forming a person in the womb, and verse 14 says, I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well. Jeremiah 1:5 records God saying that He knew Jeremiah before he was formed. From these teachings, Christians have long held that human life is sacred and should be protected at every stage, from conception to natural death. The commandment Thou shalt not kill (Exodus 20:13) protects innocent life.\n\nThis conviction shapes many issues: abortion, care for the elderly and disabled, end of life decisions, violence, war, capital punishment and care for refugees. Thoughtful Christians sometimes disagree on how to apply these principles, especially on war and capital punishment, but they agree that every person deserves respect and care. Christians are also called to compassion. Proverbs 31:8 and 9 says, Open thy mouth for the dumb in the cause of all such as are appointed to destruction. Open thy mouth, judge righteously, and plead the cause of the poor and needy.\n\nRespect for life is practical. Support expectant mothers, welcome children, visit the sick and lonely, and treat everyone with dignity regardless of race, ability, age or income. Speak with grace to people who disagree or who have suffered loss. Truth and compassion go together.\n\nWorked example: a church helps a young mother with supplies, counsel and friendship. Common mistake: talking about issues without caring for the people involved. Pair conviction with kindness.\n\nYour task: (1) Explain why Christians believe life is sacred. (2) List four ways a church can protect and serve life. (3) Write how you would speak with respect to someone who disagrees.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome back. Listen, every human being has worth because God made us in His own image.\n\nGenesis 1:27 says, So God created man in his own image, in the image of God created he him. Psalm 139:14 says, I will praise thee; for I am fearfully and wonderfully made. Psalm 139 also describes God forming a person in the womb. From these teachings, Christians have long held that human life is sacred and should be protected at every stage, from conception to natural death. Exodus 20:13 says, Thou shalt not kill.\n\nNow watch this. This conviction shapes issues like abortion, care for the elderly and disabled, end of life decisions, violence, war and care for refugees. Thoughtful Christians sometimes disagree on how to apply these principles, especially on war and capital punishment, but all agree that every person deserves respect and care. Proverbs 31:8 and 9 says, Open thy mouth, judge righteously, and plead the cause of the poor and needy.\n\nRespect for life is practical. Support mothers, welcome children, visit the sick and lonely, and treat everyone with dignity. Speak with grace to those who disagree or who have suffered loss.\n\nYour task is to explain why life is sacred, list four ways a church can serve life and write how to speak respectfully with someone who disagrees. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Life and Human Dignity$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Justice, Race and Care for the Poor$j$, $j${"readings": [{"title": "Proverbs 31 (King James Version)", "url": "/portal/bible/Proverbs/31"}], "body": "Justice means treating people fairly according to God's standard. Micah 6:8 says to do justly, and Deuteronomy 16:20 says, That which is altogether just shalt thou follow. God commands care for the poor, the stranger, the widow and the orphan. Proverbs 14:31 says, He that oppresseth the poor reproacheth his Maker: but he that honoureth him hath mercy on the poor. James 2 warns against showing favoritism to the rich and neglecting the poor. Jesus said in Matthew 25:40, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me.\n\nThe Bible teaches the unity and equality of all people before God. Acts 17:26 says that God hath made of one blood all nations of men. Galatians 3:28 says, There is neither Jew nor Greek, there is neither bond nor free, there is neither male nor female: for ye are all one in Christ Jesus. Racism, which treats people as less valuable because of race, is contrary to God's Word. American history includes slavery, segregation and the civil rights movement, in which many Christians, such as Dr. Martin Luther King Jr., worked for justice, while others failed to speak. We learn from this to stand for fair treatment today.\n\nCare for the poor includes giving, hospitality, fair wages, honest courts and honest businesses. Christians help through churches, food pantries, mentoring, job training and advocacy. Help should respect the dignity of those served. 2 Thessalonians 3:10 also teaches the value of work. Wise charity avoids both neglect and enabling harm.\n\nWorked example: a youth group runs a monthly food drive and also sits to eat and talk with neighbors. Common mistake: serving from a distance without listening. Learn people's needs and names.\n\nYour task: (1) Define justice. (2) Explain Acts 17:26 and Galatians 3:28 in your own words. (3) Plan a service project for your church or school.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome back. Listen, God cares deeply about justice and about how we treat people.\n\nJustice means treating people fairly by God's standard. Micah 6:8 says to do justly. Deuteronomy 16:20 says, That which is altogether just shalt thou follow. God commands care for the poor, the stranger, the widow and the orphan. Jesus said in Matthew 25:40, Inasmuch as ye have done it unto one of the least of these my brethren, ye have done it unto me.\n\nNow watch this. The Bible teaches the unity of all people. Acts 17:26 says God hath made of one blood all nations of men. Galatians 3:28 says, ye are all one in Christ Jesus. Racism, treating people as less valuable because of race, is contrary to God's Word. American history includes slavery, segregation and the civil rights movement, in which many Christians, such as Dr. Martin Luther King Jr., worked for justice, while others failed to speak. We learn to stand for fair treatment today.\n\nCare for the poor includes giving, hospitality, fair wages and honest courts. Help should respect the dignity of those served. Wise charity avoids both neglect and enabling harm.\n\nLearn people's needs and names.\n\nYour task is to define justice, explain Acts 17:26 and Galatians 3:28 and plan a service project. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Justice, Race and Care for the Poor$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 Technology, Media and Artificial Intelligence$j$, $j${"readings": [{"title": "Philippians 4 (King James Version)", "url": "/portal/bible/Philippians/4"}], "body": "Technology is a gift that can be used well or badly. The internet, social media, games and artificial intelligence, or AI, offer powerful tools for learning, work and ministry. They also bring ethical challenges. 1 Corinthians 10:31 says, Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God. That includes what we click, post, stream and create.\n\nGuidelines for Christian technology use: First, protect truth. Do not spread rumors, edited images or fake news. Check sources before sharing. Deepfakes are false videos or voices created by AI, and using them to deceive or hurt someone is wrong. Second, protect privacy and dignity. Do not share private information or embarrassing images of others, and never send or request inappropriate pictures. Third, protect your mind. Philippians 4:8 calls us to think on things that are true, pure and lovely. Limit content that glorifies violence, lust or hate, and watch for habits that waste time. Fourth, protect relationships. Put phones down at meals, worship and conversation. Fifth, protect honesty. If you use AI for study, follow your school rules, learn from it, check its answers and say when it helped. AI can make mistakes and cannot replace your own thinking, conscience or prayer. Colossians 3:17 says, whatsoever ye do in word or deed, do all in the name of the Lord Jesus.\n\nCompanies, governments and users share responsibility for fairness, safety and honesty in technology.\n\nWorked example: you are asked to use AI to write your essay. Use it only as the teacher allows, write your own thoughts, check facts and cite help. Common mistake: believing AI answers are always correct. Verify them.\n\nYour task: (1) Define deepfake. (2) List four rules for ethical technology use. (3) Write your own rules for using AI in schoolwork.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome back. Listen, technology is a gift, and it carries moral responsibility.\n\nFirst Corinthians 10:31 says, Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God. That includes what we click, post, stream and create with the internet, social media, games and artificial intelligence.\n\nNow watch this. Here are five guidelines. Protect truth. Do not spread rumors, edited images or fake news. A deepfake is a false video or voice made by AI, and using it to deceive or hurt is wrong. Protect privacy and dignity. Never share private information or embarrassing images, and never send or ask for inappropriate pictures. Protect your mind. Philippians 4:8 calls us to think on things that are true, pure and lovely. Protect relationships. Put phones down at meals, worship and conversation. Protect honesty. If you use AI for study, follow your school rules, learn from it, check its answers and say when it helped.\n\nAI can make mistakes and cannot replace your own thinking, conscience or prayer. Colossians 3:17 says, whatsoever ye do in word or deed, do all in the name of the Lord Jesus.\n\nYour task is to define deepfake, list four rules and write your rules for using AI in schoolwork. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 Technology, Media and Artificial Intelligence$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Citizenship, Conscience and Living Faith$j$, $j${"readings": [{"title": "1 Peter 3 (King James Version)", "url": "/portal/bible/1Peter/3"}], "body": "Christians live in two worlds: as citizens of heaven (Philippians 3:20) and as citizens of an earthly nation. Romans 13:1 says, Let every soul be subject unto the higher powers. For there is no power but of God. Christians pray for leaders (1 Timothy 2:1 and 2), pay taxes (Matthew 22:21), obey just laws, vote, serve and work for the good of the community. Jeremiah 29:7 says, seek the peace of the city whither I have caused you to be carried away captives, and pray unto the LORD for it.\n\nSometimes the law and conscience conflict. Acts 5:29 says, We ought to obey God rather than men. Daniel refused to stop praying, and the apostles continued to preach. Yet they acted with respect, accepted consequences and avoided violence. Civil disobedience is a serious step to use only when a law requires sin, after prayer and wise counsel.\n\nChristians will meet people who disagree. 1 Peter 3:15 says, But sanctify the Lord God in your hearts: and be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear. We witness with gentleness, listen first and treat others as made in God's image. Colossians 4:6 says, Let your speech be alway with grace, seasoned with salt.\n\nEthical living is more than knowing right. It is doing right. James 1:22 says, But be ye doers of the word, and not hearers only, deceiving your own selves. A Christian ethic is lived in homes, schools, workplaces and communities, empowered by the Holy Spirit and given grace when we fail.\n\nWorked example: a classmate asks why you do not join in cheating. Answer calmly, I want to be honest because I follow Jesus, and offer to study together. Common mistake: arguing to win. Speak with gentleness and respect.\n\nYour task: (1) Explain how a Christian can be a good citizen. (2) Explain when Acts 5:29 applies. (3) Write a gentle answer for a question about your faith.\n\nFlorida standards: NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Christian Ethics course outcomes, ELA.K12.EE.1.1", "script": "Welcome back. Listen, we live in two worlds. We are citizens of heaven and citizens of an earthly nation.\n\nRomans 13:1 says, Let every soul be subject unto the higher powers. Christians pray for leaders, pay taxes, obey just laws, vote, serve and work for the good of the community. Jeremiah 29:7 says, seek the peace of the city whither I have caused you to be carried away captives, and pray unto the LORD for it.\n\nNow watch this. Sometimes law and conscience conflict. Acts 5:29 says, We ought to obey God rather than men. Daniel refused to stop praying, and the apostles continued to preach. Yet they acted with respect and accepted the consequences. Disobedience is a serious step only when a law requires sin, after prayer and wise counsel.\n\nWhen people disagree, First Peter 3:15 says, be ready always to give an answer to every man that asketh you a reason of the hope that is in you with meekness and fear. Colossians 4:6 says, Let your speech be alway with grace, seasoned with salt.\n\nEthical living is not only knowing right. It is doing right. James 1:22 says, be ye doers of the word, and not hearers only.\n\nYour task is to explain good citizenship, explain when Acts 5:29 applies and write a gentle answer about your faith. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Citizenship, Conscience and Living Faith$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: Ethics in Society$j$, $j${"prompt": "Write a report of at least 250 words on Christian ethics in society. Use complete sentences and label each part. Do not name real private individuals. James 1:22 says, But be ye doers of the word, and not hearers only, deceiving your own selves.\n\nPart 1: Explain why Christians believe human life has dignity and give two ways to serve life with compassion.\nPart 2: Explain biblical justice, the unity of all people and two ways to care for the poor.\nPart 3: Write five rules for ethical use of technology and artificial intelligence.\nPart 4: Explain what Romans 13:1 and Acts 5:29 teach about citizenship and conscience.\nPart 5: Describe how you would answer a respectful question about your faith.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 25 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: Ethics in Society$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Doers of the Word$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes one problem in your community where Christians can serve, (2) explains a first step you could take, (3) tells how you will speak with gentleness and respect, and (4) connects your answer to Micah 6:8, Matthew 25:40 or James 1:22. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can we stand for truth while treating others with kindness? Do not name real private individuals."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Doers of the Word$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Life and Human Dignity$j$, $j${"questions": [{"q": "Christians believe human life has worth because people are made:", "options": ["By government", "By chance", "In the image of God", "By wealth"]}, {"q": "Exodus 20:13 says:", "options": ["Honor thy father", "Thou shalt not covet", "Remember the Sabbath", "Thou shalt not kill"]}, {"q": "Proverbs 31:8 and 9 calls us to:", "options": ["Ignore the weak", "Speak up for the poor and needy", "Seek wealth", "Avoid conflict"]}, {"q": "Respect for life is shown by:", "options": ["Anger only", "Compassion and practical help", "Silence only", "Debate only"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Life and Human Dignity$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,3,1,1}'::int[], array[$j$Genesis 1:27 teaches this.$j$,$j$It protects innocent life.$j$,$j$God's people plead for those without a voice.$j$,$j$Truth and compassion go together.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Life and Human Dignity$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Justice, Race and Care for the Poor$j$, $j${"questions": [{"q": "Acts 17:26 teaches that God made all nations of:", "options": ["Many origins", "Warriors", "One blood", "Rich families"]}, {"q": "Jesus said serving the least of these is like serving:", "options": ["A stranger only", "Him", "A teacher only", "A king"]}, {"q": "Racism is contrary to God's Word because:", "options": ["It is rare", "Race does not exist", "All people are made in His image", "People are identical"]}, {"q": "Wise charity should respect:", "options": ["Only donors", "Silence", "The dignity of those served", "Public praise"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Justice, Race and Care for the Poor$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,2,2}'::int[], array[$j$All people share one human family.$j$,$j$Matthew 25:40 identifies Christ with the needy.$j$,$j$Every person has equal dignity.$j$,$j$Help should honor people.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Justice, Race and Care for the Poor$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: Technology, Media and Artificial Intelligence$j$, $j${"questions": [{"q": "A deepfake is:", "options": ["A password", "A study guide", "A real recording", "A false video or voice made by AI"]}, {"q": "When using AI for schoolwork you should:", "options": ["Copy it without reading", "Hide it", "Follow your school rules, check answers and give credit", "Trust it fully"]}, {"q": "1 Corinthians 10:31 says to do all things:", "options": ["In secret", "For money", "For likes", "To the glory of God"]}, {"q": "Sending inappropriate pictures is:", "options": ["Harmful and wrong", "Harmless", "Required", "Funny"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Technology, Media and Artificial Intelligence$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,0}'::int[], array[$j$Deepfakes imitate real people to deceive.$j$,$j$Honesty and verification matter.$j$,$j$Technology use is under God's glory.$j$,$j$It damages dignity and can be illegal for minors.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: Technology, Media and Artificial Intelligence$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Citizenship, Conscience and Living Faith$j$, $j${"questions": [{"q": "Acts 5:29 says we ought to obey:", "options": ["Men rather than God", "No one", "Only parents", "God rather than men"]}, {"q": "1 Peter 3:15 says to give an answer with:", "options": ["Meekness and fear", "Pride", "Silence", "Anger"]}, {"q": "A good Christian citizen may:", "options": ["Ignore all laws", "Avoid neighbors", "Hide from public life", "Pray, vote, serve and obey just laws"]}, {"q": "James 1:22 calls us to be:", "options": ["Critics only", "Hearers only", "Doers of the word", "Silent"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Citizenship, Conscience and Living Faith$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,3,2}'::int[], array[$j$God's command is the highest authority.$j$,$j$Witness is gentle and respectful.$j$,$j$Faith works for the good of the community.$j$,$j$Faith must be lived.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Citizenship, Conscience and Living Faith$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Ethics in Society$j$, $j${"questions": [{"q": "Genesis 1:27 teaches that people are made:", "options": ["Alike", "By accident", "Equal in wealth", "In the image of God"]}, {"q": "A deepfake is:", "options": ["A prayer", "A permission slip", "A password", "A false video or voice made by AI"]}, {"q": "Acts 17:26 says God made all nations of:", "options": ["One blood", "Many kinds", "Soldiers", "Rich men"]}, {"q": "Jesus said serving the least is serving:", "options": ["A friend only", "A stranger only", "A ruler only", "Him"]}, {"q": "Christians pay taxes because:", "options": ["It earns salvation", "Taxes are secret", "It is optional", "Jesus taught to render to Caesar what is Caesar's"]}, {"q": "Acts 5:29 applies when a law:", "options": ["Is new", "Requires sin", "Is inconvenient", "Is unpopular"]}, {"q": "When answering questions about faith, Christians should show:", "options": ["Silence", "Gentleness and respect", "Anger", "Pride"]}, {"q": "James 1:22 says to be:", "options": ["Observers", "Hearers only", "Critics", "Doers of the word"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Ethics in Society$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,0,3,3,1,1,3}'::int[], array[$j$Human dignity comes from God.$j$,$j$Deepfakes deceive.$j$,$j$All people share one origin.$j$,$j$Matthew 25:40.$j$,$j$Matthew 22:21.$j$,$j$Obey God rather than men only when commanded to sin.$j$,$j$1 Peter 3:15.$j$,$j$Faith is lived.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Ethics in Society$j$ on conflict (item_id) do nothing;
